import importlib
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
FUNCTIONS = ['nb_aatm', 'nb_aatm_1996', 'nb_abar', 'nb_adiv', 'nb_agr', 'nb_agr_simplified', 'nb_background_subtract', 'nb_bands', 'nb_bench_cases', 'nb_bench_run', 'nb_bench_scene', 'nb_butter_sos', 'nb_cmet', 'nb_compliance', 'nb_dem_sample', 'nb_dz', 'nb_enclosure', 'nb_enclosure_surfaces', 'nb_energy_sum', 'nb_estimate_lw', 'nb_fingerprint', 'nb_geom2d', 'nb_ground_factors', 'nb_lateral', 'nb_material', 'nb_obstacles', 'nb_profile_dem', 'nb_receiver_3d', 'run_acoustic_case', 'run_case_2d', 'run_case_3d', 'run_field_2d', 'run_field_3d']


def manifest():
    with open(os.path.join(HERE, "manifest.json"), "r", encoding="utf-8") as f:
        return json.load(f)


def _wire(mods):
    ns = {}
    for name, m in mods.items():
        ns[name] = getattr(m, name)
    for m in mods.values():
        m.__dict__.update(ns)
    globals().update(ns)
    return ns


def load(reload=False):
    mods = {}
    for name in FUNCTIONS:
        full = __name__ + "." + name
        if reload and full in sys.modules:
            mods[name] = importlib.reload(sys.modules[full])
        else:
            mods[name] = importlib.import_module(full)
    return _wire(mods)


def reload():
    importlib.invalidate_caches()
    return load(reload=True)
